from datetime import time, timezone, timedelta

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since midnight.
    :param tz: Timezone for the time object. If None, the time will be naive.
    :return: Time
    """
    if nanoseconds < 0 or nanoseconds >= 24 * 60 * 60 * 10**9:
        raise ValueError("nanoseconds must be between 0 and 24*60*60*10**9")

    seconds = nanoseconds // 10**9
    microseconds = (nanoseconds % 10**9) // 10**3

    naive_time = time(seconds, microseconds // 1000)

    if tz is not None:
        if not isinstance(tz, (timezone, timedelta)):
            raise TypeError("tz must be a timezone or timedelta")
        return naive_time.replace(tzinfo=tz)
    else:
        return naive_time

