import time
from functools import wraps

def unit_of_work(metadata=None, timeout=None):
    """
    Decorator to manage transaction properties such as metadata and timeout.

    :param metadata: A dictionary containing metadata to be attached to the transaction.
    :type metadata: dict

    :param timeout: The timeout for the transaction in seconds. None for default.
    :type timeout: float or None
    """
    def decorator(func):
        @wraps(func)
        def wrapper(tx, *args, **kwargs):
            if metadata is not None:
                tx.metadata = metadata
            if timeout is not None and timeout < 0:
                raise ValueError("Timeout value must not be negative")
            if timeout is not None:
                start_time = time.time()
                while True:
                    result = func(tx, *args, **kwargs)
                    if time.time() - start_time > timeout:
                        raise TimeoutError("Transaction exceeded the specified timeout")
                    return result
            else:
                return func(tx, *args, **kwargs)
        return wrapper
    return decorator

