def round_half_to_even(n):
    """
    This function rounds a number to the nearest integer. If the number is exactly halfway between two integers,
    it rounds to the nearest even number according to IEEE 754 standard.

    :param n: A number to round
    :return: The rounded number
    """
    if not isinstance(n, (int, float)):
        raise TypeError("Input must be a number")

    if n >= 0:
        return int(n + 0.5 - 0.5 * (n + 0.5) % 1)
    else:
        return int(n - 0.5 + 0.5 * (n - 0.5) % 1)

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, using "round half to even" (bankers' rounding) method.

    :param n: The number to round
    :return: The rounded number
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    int_part, frac_part = divmod(abs(n), 1)
    if frac_part == 0.5:
        if int_part % 2 == 0:
            return int(n)
        else:
            return int(n) + (1 if n > 0 else -1)
    else:
        return round(n)

def round_half_to_even(n):
    if isinstance(n, (int, float)):
        if n - int(n) == 0.5:
            if int(n) % 2 == 0:
                return int(n)
            else:
                return int(n) + 1
        else:
            return round(n)
    else:
        raise ValueError("Input must be an integer or float")

