def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if not cmd:
        return ()

    normalized_cmd = []
    for part in cmd:
        if len(part) > 3 and part[:3] == '#!/' and '/' in part[3:]:
            # Replace backslashes with forward slashes in the shebang
            shebang = part[:3] + part[3:].replace('\\', '/')
            normalized_cmd.append(shebang)
        else:
            normalized_cmd.append(part)

    return tuple(normalized_cmd)

