    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        import traceback

        def format_stack(stack, level):
            if level <= 0:
                return ""
            return "\n".join(traceback.format_list(stack[:level]))

        def format_args(args):
            return ", ".join(f"{k}={v!r}" for k, v in args.items())

        def format_tb(exc_info, path_level):
            if exc_info and exc_info[2]:
                tb = exc_info[2]
                tb_list = []
                while tb:
                    tb_list.append(tb)
                    tb = tb.tb_next
                return format_stack(tb_list, path_level)
            return ""

        try:
            exc_info = sys.exc_info()
            exc_type = exc_info[0]
            exc_value = exc_info[1]
            exc_traceback = exc_info[2]
            tb_str = format_tb(exc_info, max_path_level)
