def check_digests_present_and_used(self, manifest_files, digests_used):
    """
    Check that all digests in the provided manifest files are present in the digests_used list and that each digest is used at least once.
    """
    if not manifest_files:
        raise ValueError("Manifest files list cannot be empty")

    if not digests_used:
        raise ValueError("Digests used list cannot be empty")

    for manifest_file in manifest_files:
        if not isinstance(manifest_file, dict):
            raise ValueError("Each manifest file must be a dictionary")

        if 'digests' not in manifest_file:
            raise ValueError("Each manifest file must contain a 'digests' key")

        manifest_digests = manifest_file['digests']
        if not isinstance(manifest_digests, list):
            raise ValueError("The 'digests' value must be a list")

        for digest in manifest_digests:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} from manifest is not present in digests_used list")

        if not any(digest in digests_used for digest in manifest_digests):
            raise ValueError(f"No digests from manifest file {manifest_file} are used in digests_used list")

    return True

