def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    import os

    if not os.path.isdir(file_folder):
        raise ValueError("file_folder must be a valid directory")

    if not os.path.isfile(file_path):
        raise ValueError("file_path must be a valid file")

    file_extension = os.path.splitext(file_path)[1]

    if file_extension not in ['.xml', '.txt']:
        return {'type': 'unknown', 'path': file_path}

    if 'asset' in prefix:
        return {'type': 'asset', 'path': file_path}
    elif 'rendition' in prefix:
        return {'type': 'rendition', 'path': file_path}
    else:
        return {'type': 'unknown', 'path': file_path}

