def _extract_number_and_supplment_from_issue_element(issue):
    if not isinstance(issue, str):
        raise ValueError("Input must be a string")

    issue = issue.strip()
    if not issue:
        raise ValueError("Input string cannot be empty")

    number = None
    suppl = None
    suppl_parts = []

    # Extract number
    if issue.isdigit():
        number = int(issue)
    else:
        parts = issue.split()
        for part in parts:
            if part.isdigit():
                number = int(part)
                break

    if number is None:
        raise ValueError("No number found in the input")

    # Extract suppl
    for part in parts:
        if part.lower() in ['suppl', 'spe', '-spe']:
            suppl = 'Suppl'
            suppl_parts.append('Suppl')
        elif part.lower() == 'pr':
            suppl = 'Pr'
            suppl_parts.append('Pr')
        elif part.isdigit():
            suppl_parts.append(part)
        elif '-' in part:
            suppl_parts.extend(part.split('-'))

    suppl = ' '.join(suppl_parts)

    return number, suppl

