    if not commands:
        raise ValueError("Commands list cannot be empty")

    if env and not isinstance(env, dict):
        raise ValueError("env must be a dictionary if provided")

    try:
        if isinstance(commands, list):
            command = [commands[0], *args]
        else:
            command = [commands, *args]

        if hide_stderr:
            stderr = subprocess.DEVNULL
        else:
            stderr = None

        result = subprocess.run(command, cwd=cwd, env=env, capture_output=True, text=True, check=True)

        if verbose:
            print("Command output:", result.stdout)

        return result.stdout

    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {commands}") from e

    except subprocess.CalledProcessError as e:
        error_message = f"Command failed with return code {e.returncode}: {e.stderr}"
        if not hide_stderr:
            error_message += "\nStderr:\n" + e.stderr
        raise subprocess.CalledProcessError(e.returncode, e.cmd, error_message) from e

