    merged_dict = {}
    for key, value in nodes:
        if key.value not in merged_dict:
            merged_dict[key.value] = value
        else:
            if isinstance(merged_dict[key.value], ruamel.yaml.nodes.MappingNode) and isinstance(value, ruamel.yaml.nodes.MappingNode):
                merged_dict[key.value] = deep_merge(merged_dict[key.value], value)
            else:
                merged_dict[key.value] = value
    return [(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=key), value) for key, value in merged_dict.items()]

