def parse_subparser_arguments(unparsed_arguments, subparsers):
    import argparse
    from collections.abc import Mapping

    if not isinstance(unparsed_arguments, list):
        raise TypeError("Expected unparsed_arguments to be a list")
    if not isinstance(subparsers, Mapping):
        raise TypeError("Expected subparsers to be a dictionary")

    parsed_args = {}
    remaining_args = unparsed_arguments

    for subparser_name, parser in subparsers.items():
        if not isinstance(parser, argparse.ArgumentParser):
            raise TypeError(f"Expected {subparser_name} to be an instance of argparse.ArgumentParser")

        # Use ArgumentDefaultsHelpFormatter to show default values in help output
        subparser = parser.add_subparsers(dest=subparser_name, formatter_class=argparse.ArgumentDefaultsHelpFormatter)

        for arg in subparsers[subparser_name].subcommands.values():
            subparser.add_parser(arg)

        # Parse the arguments with the subparser
        namespace, remaining = parser.parse_known_args(remaining_args)
        parsed_args[subparser_name] = namespace
        remaining_args = [arg for arg in remaining if arg not in (Namespace(**vars(namespace))._get_kwargs())]

    return parsed_args, remaining_args

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {}
    remaining_arguments = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        arg_tuple_list = tuple(remaining_arguments)
        namespace = parser._actions[0].default  # start with default namespace
        for action in parser._actions:
            idx = next((i for i, arg in enumerate(arg_tuple_list) if action._handle_parsed_arg(arg, namespace=namespace)), -1)
            if idx != -1:
                remaining_arguments = arg_tuple_list[:idx] + arg_tuple_list[idx+1:]
                namespace = action._parse_args([arg_tuple_list[idx]], namespace)

        parsed_arguments[subparser_name] = namespace

    return parsed_arguments, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for subparser_name, subparser in subparsers.items():
        try:
            namespace, args = subparser.parse_known_args(remaining_args)
            remaining_args = args
            parsed_args[subparser_name] = namespace
        except Exception as e:
            # If parsing fails, continue to the next subparser
            continue

    return parsed_args, remaining_args

