def vertex3tuple(vertices):
    n = len(vertices)
    if n < 4:
        raise ValueError("Input must contain at least 4 vertices.")

    result = []
    for i in range(n):
        prev = (i - 1) % n
        next_vertex = (i + 1) % n
        result.append((vertices[prev], vertices[i], vertices[next_vertex]))

    return result

