import subprocess
from pathlib import PosixPath
from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        # Ensure the temporary path is a PosixPath for consistency
        if isinstance(tmp_path, str):
            tmp_path = PosixPath(tmp_path)

        # Ensure the temporary path exists
        tmp_path.mkdir(parents=True, exist_ok=True)

        # Define the full path to the archive
        full_archive_path = tmp_path / archive_path.split("/")[-1]

        # Uncompress the archive
        if archive_path.endswith(".zip"):
            subprocess.run(["unzip", full_archive_path], check=True)
        elif archive_path.endswith((".tar", ".gz", ".tgz")):
            subprocess.run(["tar", "-xvf", full_archive_path], check=True)
        else:
            raise ValueError("Unsupported archive format")

        # Return the file repo url
        return str(tmp_path / archive_path.split("/")[-1].replace(".zip", "").replace(".tar", "").replace(".gz", "").replace(".tgz", ""))

    except FileNotFoundError as e:
        raise FileNotFoundError(f"Archive not found: {archive_path}") from e
    except subprocess.CalledProcessError as e:
        raise subprocess.CalledProcessError(f"Failed to uncompress archive: {archive_path}") from e
    except Exception as e:
        raise Exception(f"An error occurred during repository preparation: {e}") from e

