def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        # Construct the command with arguments
        full_command = [commands] + args

        # Configure process arguments
        process_args = {
            'args': full_command,
            'cwd': cwd,
            'env': env
        }

        # Handle stdout according to verbose and hide_stderr
        if not verbose and hide_stderr:
            process_args['stderr'] = subprocess.PIPE
        elif hide_stderr:
            process_args['stderr'] = subprocess.DEVNULL
        else:
            process_args['stderr'] = None

        # Execute the command
        with subprocess.Popen(**process_args, stdout=subprocess.PIPE, stderr=subprocess.PIPE) as process:
            stdout, stderr = process.communicate()

            # Decode the output if it's not None
            if stdout:
                stdout = stdout.decode('utf-8').strip()
            if stderr:
                stderr = stderr.decode('utf-8').strip()

            # Print verbose output
            if verbose:
                print(f"stdout: {stdout}")
                print(f"stderr: {stderr}")

            # Return the result
            return {
                'stdout': stdout,
                'stderr': stderr,
                'returncode': process.returncode
            }

    except Exception as e:
        # Handle any exceptions that occur during the command execution
        return {
            'stdout': None,
            'stderr': str(e),
            'returncode': -1
        }
    finally:
        if verbose:
            print("Command executed.")

