def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None
) -> Set[Node]:
    if not roots:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        if p != prop:
            continue
        if o in roots:
            roots.remove(o)
        if s not in roots:
            roots.add(s)

    return roots

