def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        def make_value(bin_content):
            return bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if len(field_names) != (3 if get_coordinate == "left" else 2):
        raise ValueError("field_names must have 2 fields if get_coordinate is 'left', 3 otherwise")

    points = []
    for bin_idx, bin_content in enumerate(hist.bins):
        if get_coordinate == "left":
            x = hist.x_min + bin_idx * hist.width
        elif get_coordinate == "right":
            x = hist.x_min + (bin_idx + 1) * hist.width
        elif get_coordinate == "middle":
            x = hist.x_min + (bin_idx + 0.5) * hist.width

        value = make_value(bin_content)
        points.append([x, *value])

    if scale:
        if scale == True:
            scale = hist.scale
        for point in points:
            point[1:] = [coord * scale for coord in point[1:]]

    return {
        "points": points,
        "field_names": field_names,
        "scale": scale
    }

