    if len(field_names) != len(list(make_value(bin) for bin in hist[0])):
        raise ValueError("The number of field names must match the number of values per bin.")

    graph = []

    for bin in hist:
        point = make_value(bin)
        if len(point) != len(field_names):
            raise ValueError("The number of values in the bin does not match the number of field names.")

        if get_coordinate == "left":
            point = (bin, *point[1:])
        elif get_coordinate == "right":
            point = (*point[:-1], bin)
