    from zope.interface import providedBy, Invalid, directlyProvides, implementer
    import inspect

    if not tentative and not iface.providedBy(candidate):
        raise Invalid(f"Candidate does not claim to provide {iface}")

    class_methods = set(dir(candidate.__class__))
    interface_methods = set(iface.namesFlat())

    for method in interface_methods:
        method_func = getattr(candidate, method, None)
        if method not in class_methods or not callable(method_func):
            raise Invalid(f"Method {method} is not defined or not callable")

        method_argspec = inspect.getfullargspec(method_func)
        method_interface_argspec = iface[method]

        if method_argspec.args != method_interface_argspec.args:
            raise Invalid(f"Method {method} has incorrect signature")

    class_attributes = set(dir(candidate.__class__))
    interface_attributes = set(iface.namesFlat())

    for attr in interface_attributes:
        if attr.startswith('_'):
            continue
        if attr not in class_attributes:
            raise Invalid(f"Attribute {attr} is not defined")

    return True

