class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.freq_counter = {}
        self.freq_heap = []

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        self.increase_frequency(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.cache:
            self.cache[key] = value
            self.increase_frequency(key)
        else:
            if len(self.cache) >= self.capacity:
                self.evict()
            self.cache[key] = value
            self.freq_counter[key] = 1
            heapq.heappush(self.freq_heap, (1, key))

    def increase_frequency(self, key: int) -> None:
        freq = self.freq_counter[key]
        heapq.heappush(self.freq_heap, (freq + 1, key))
        del self.freq_counter[key]
        self.freq_counter[key] = freq + 1

    def evict(self) -> None:
        while self.freq_heap:
            freq, key = heapq.heappop(self.freq_heap)
            if key in self.cache:
                del self.cache[key]
                del self.freq_counter[key]
                break

