def parse(self, timestr, default=None,
          ignoretz=False, tzinfos=None, **kwargs):
    if not isinstance(timestr, str):
        raise TypeError("Non-string or character stream input")

    try:
        if ignoretz:
            dt = dateutil_parse(timestr, ignoretz=ignoretz, **kwargs)
        else:
            dt = dateutil_parse(timestr, tzinfos=tzinfos, **kwargs)
    except ValueError as e:
        raise ParserError(f"Invalid or unknown string format: {timestr}") from e
    except OverflowError as e:
        raise OverflowError(f"Parsed date exceeds the largest valid C integer on your system: {timestr}") from e

    if default is not None and isinstance(default, datetime.datetime):
        if ignoretz:
            dt = default.replace(year=dt.year, month=dt.month, day=dt.day,
                                 hour=dt.hour, minute=dt.minute, second=dt.second,
                                 microsecond=dt.microsecond)
        else:
            dt = default.replace(year=dt.year, month=dt.month, day=dt.day,
                                 hour=dt.hour, minute=dt.minute, second=dt.second,
