    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    # Check if the document is in JSON format
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        pass  # Not in JSON format, continue to try XRD

    # Check if the document is in XRD format
    try:
        root = etree.fromstring(document)
        subject = root.find('{http://www.w3.org/ns/xrd#}Subject')
        if subject is not None:
            return {
                'subject': subject.text,
                'links': [
                    {'rel': link.get('{http://www.w3.org/ns/xrd#}rel'), 'href': link.get('{http://www.w3.org/ns/xrd#}href')}
                    for link in root.findall('{http://www.w3.org/ns/xrd#}Link')
                ]
            }
    except etree.XMLSyntaxError:
        pass  # Not in XRD format, raise an exception

    raise ValueError("Invalid Diaspora webfinger document (neither JSON nor XRD)")

