import json
import xml.etree.ElementTree as ET

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Check if the document is in JSON format
        return json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, assume it is in XRD format
        try:
            root = ET.fromstring(document)
            properties = root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Property')
            result = {}
            for prop in properties:
                result[prop.get('name')] = prop.text
            return result
        except ET.ParseError:
            raise ValueError("Invalid JSON or XRD format")

