    """
    Inserts a value into a nested key of a dictionary.

    :param dic: A dictionary object to insert the nested key and value into.
    :param val: The value to insert into the nested key.
    :param key: The first key in the chain of keys.
    :param keys: The subsequent keys in the chain of keys.
    :return: None
    """
    try:
        if len(keys) > 0:
            if key not in dic:
                dic[key] = {}
            dict_insert(dic[key], val, *keys)
        else:
            dic[key] = val
    except (TypeError, KeyError) as e:
        raise ValueError("Invalid dictionary structure or invalid keys") from e

