def list_of_file_names(settings_dirs, spec_option):
    """
    This method generates a list of file names from a list of directory paths,
    filtered by a specific option.

    :param settings_dirs: List of directory paths containing potential configuration files.
    :type settings_dirs: List[str]

    :param spec_option: Option to filter file names (e.g., include only .ini files).
    :type spec_option: str

    :return: A list of file names that match the specified option.
    :rtype: List[str]
    """

    import os

    # Validate input
    if not isinstance(settings_dirs, list) or not all(isinstance(item, str) for item in settings_dirs):
        raise ValueError("settings_dirs must be a list of strings")
    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string")

    # Process each directory
    file_names = []
    for directory in settings_dirs:
        if os.path.isdir(directory):
            for root, _, files in os.walk(directory):
                for file in files:
                    if file.endswith(spec_option):
                        file_names.append(os.path.join(root, file))

    return file_names

