import subprocess

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
    workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    # Validate input types
    if not isinstance(ir_workspace, object):
        raise ValueError("ir_workspace must be an instance of an object")
    if not isinstance(ir_plugin, object):
        raise ValueError("ir_plugin must be an instance of an object")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("verbose must be an integer if provided")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars must be a dictionary if provided")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dictionary if provided")

    # Prepare command
    command = ["ansible-playbook", playbook_path]
    if verbose is not None:
        command.append(f"-v" * verbose)
    if extra_vars:
        for key, value in extra_vars.items():
            command.append(f"-e")
            command.append(f"{key}={value}")
    if ansible_args:
        command.extend([f"--{key.replace('_', '-')}={value}" for key, value in ansible_args.items()])

    try:
        # Execute the command
        subprocess.run(command, check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Ansible playbook failed with return code {e.returncode}: {e}")

