import subprocess
import json
from typing import Dict, List, Any
from infrared.api.models import Workspace, Plugin

def _run_playbook(cli_args: List[str], vars_dict: Dict[str, Any], ir_workspace: Workspace, ir_plugin: Plugin) -> Dict[str, Any]:
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    try:
        # Convert vars_dict to a JSON string for ansible-extra-vars
        extra_vars = json.dumps(vars_dict)

        # Construct the ansible command
        command = ["ansible-playbook"] + cli_args + ["--extra-vars", extra_vars]

        # Run the ansible command using subprocess
        result = subprocess.run(command, check=True, capture_output=True, text=True)

        # Parse the ansible output as JSON if it's a json output
        if "json" in result.stdout:
            ansible_results = json.loads(result.stdout)
        else:
            ansible_results = {"stdout": result.stdout, "stderr": result.stderr}

        return ansible_results
    except subprocess.CalledProcessError as e:
        return {"error": str(e), "stdout": e.stdout, "stderr": e.stderr}
    except json.JSONDecodeError as e:
        return {"error": "Invalid JSON output from ansible: ", "json_error": str(e)}
    except Exception as e:
        return {"error": "An unexpected error occurred: ", "error_info": str(e)}

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    import subprocess

    ansible_cmd = ['ansible-playbook'] + cli_args + ['-e', ','.join([f'{k}={v}' for k, v in vars_dict.items()])]
    try:
        result = subprocess.run(ansible_cmd, check=True, capture_output=True, text=True)
        return result.stdout
