def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        # Check if the directory exists
        if not os.path.isdir(plugin_dir):
            raise ValueError("The provided directory does not exist.")

        # Find the plugin spec file within the directory
        spec_file_path = os.path.join(plugin_dir, 'plugin.spec')
        if not os.path.isfile(spec_file_path):
            raise FileNotFoundError("The plugin spec file does not exist in the directory.")

        # Load the plugin spec file
        with open(spec_file_path, 'r') as file:
            spec_data = json.load(file)

        # Flatten the dictionary
        def flatten_dict(d, parent_key='', sep='_'):
            items = []
            for k, v in d.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                if isinstance(v, dict):
                    items.extend(flatten_dict(v, new_key, sep=sep).items())
                else:
                    items.append((new_key, v))
            return dict(items)

        flatten_dict_result = flatten_dict(spec_data)

        return flatten_dict_result

